-- Audyt E24: prawa EXECUTE funkcji SECURITY DEFINER bez sprawdzania auth.uid() w treści (lista lokalna).
-- Wynik: nr (plik .names), kod 0 nikt, 1 zalogowani, 2/3 także anonimowi, -1 brak funkcji na produkcji.
select f.nr, coalesce((select max((case when has_function_privilege('anon', p.oid, 'execute') then 2 else 0 end) + (case when has_function_privilege('authenticated', p.oid, 'execute') then 1 else 0 end)) from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = 'public' and p.proname = f.name), -1) as code
from unnest(array[
